          if (t.box !== undefined) { drawBox(cx, yy + i * LH - 2.4, t.box); cx += 3 + 1.6; }
          else { setF(t.b); doc.setFontSize(SZ); doc.setTextColor(...(t.v ? INK : LABEL)); doc.text(t.w, cx, yy + i * LH); cx += doc.getTextWidth(t.w); }
